/*
Data Memory
- Stores data
- Inputs and Outputs
    - address: Given by program counter to get instruction at memory location
    - instruction: Instruction at pc address
*/
module data_memory(
	input wire clk, wen,
	input wire [31:0] addr,
	input wire [31:0] data_in,
	output wire [31:0] data_out
);
    wire [11:0] mem_index;
    assign mem_index = addr[13:2];

    // -------------------------------------------------------------------------
    // ASIC SRAM Macro Instantiation
    // Replace "sram_4096x32" with the exact name generated by your Memory Compiler
    // -------------------------------------------------------------------------
    sram_4096x32 u_dmem_sram (
        .clk  (clk),
        .addr (mem_index),       // 12-bit address for 4096 words
        .din  (data_in),
        .wen  (wen),
        .dout (data_out)
    );
endmodule

module sram_4096x32(
    input wire clk,
    input wire [11:0] addr,
    input wire [31:0] din,
    input wire wen,
    output reg [31:0] dout
);
    // Four bytes of addressable memory with 4096 locations
	reg [31:0] internal_memory_array [4095:0];
    always @(posedge clk) begin
        if (wen) begin
            internal_memory_array[addr] <= din;
        end
    end

    always @(*) begin
        dout = internal_memory_array[addr];
    end
endmodule